import { Routes } from "@angular/router";
import { RoutezFeatureModule } from "@_core/_route";
import { TypeFile } from "./type-file/type-file";
import { TypeFileAdd } from "./type-file/type-file-add/type-file-add";
import { UploadFile } from "./upload-file/upload-file";
import { UploadFileAdd } from "./upload-file/upload-file-add/upload-file-add";


export const Routez: Routes = new RoutezFeatureModule (
  ['File Upload'],
  'feature/file-upload'
)
.feature(TypeFile, TypeFileAdd, 'file-type', 'File Type')
.feature(UploadFile, UploadFileAdd, 'upload-file', 'Upload File')

.build();
